CREATE TABLE public.account_restrictions (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, banned_until timestamptz, reason text NOT NULL DEFAULT '', updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.account_restrictions TO service_role;
ALTER TABLE public.account_restrictions ENABLE ROW LEVEL SECURITY;
CREATE TRIGGER account_restrictions_touch BEFORE UPDATE ON public.account_restrictions FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.viewer_sessions (session_id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, device_hash text NOT NULL, device_name text NOT NULL, ip text, country text, city text, user_agent text, first_touch jsonb NOT NULL DEFAULT '{}', last_touch jsonb NOT NULL DEFAULT '{}', state text NOT NULL DEFAULT 'active', current_episode_id uuid REFERENCES public.episodes(id) ON DELETE SET NULL, watched_seconds numeric NOT NULL DEFAULT 0, last_seen_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.viewer_sessions TO authenticated; GRANT ALL ON public.viewer_sessions TO service_role;
ALTER TABLE public.viewer_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own observed sessions" ON public.viewer_sessions FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE INDEX viewer_sessions_user_seen ON public.viewer_sessions(user_id,last_seen_at DESC);
CREATE TRIGGER viewer_sessions_touch BEFORE UPDATE ON public.viewer_sessions FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.viewer_watch_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, session_id uuid NOT NULL REFERENCES public.viewer_sessions(session_id) ON DELETE CASCADE, episode_id uuid NOT NULL REFERENCES public.episodes(id) ON DELETE CASCADE, watched_seconds numeric NOT NULL DEFAULT 0, started_at timestamptz NOT NULL DEFAULT now(), last_watched_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session_id,episode_id));
GRANT SELECT ON public.viewer_watch_history TO authenticated; GRANT ALL ON public.viewer_watch_history TO service_role;
ALTER TABLE public.viewer_watch_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own viewing history" ON public.viewer_watch_history FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE TRIGGER viewer_history_touch BEFORE UPDATE ON public.viewer_watch_history FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.security_blocks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, value text NOT NULL, reason text NOT NULL DEFAULT '', blocked_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,value));
GRANT ALL ON public.security_blocks TO service_role;
ALTER TABLE public.security_blocks ENABLE ROW LEVEL SECURITY;
CREATE TRIGGER security_blocks_touch BEFORE UPDATE ON public.security_blocks FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE OR REPLACE FUNCTION public.account_access_allowed() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.account_restrictions WHERE user_id=auth.uid() AND banned_until>now()) AND NOT EXISTS(SELECT 1 FROM public.viewer_sessions WHERE session_id::text=auth.jwt()->>'session_id' AND revoked_at IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM public.security_blocks WHERE kind='email' AND value=lower(auth.jwt()->>'email')); $$;
REVOKE ALL ON FUNCTION public.account_access_allowed() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.account_access_allowed() TO authenticated,service_role;
CREATE POLICY "Restrict signed in catalogue access" ON public.series AS RESTRICTIVE FOR ALL TO authenticated USING(public.account_access_allowed()) WITH CHECK(public.account_access_allowed());
CREATE POLICY "Restrict signed in episode access" ON public.episodes AS RESTRICTIVE FOR ALL TO authenticated USING(public.account_access_allowed()) WITH CHECK(public.account_access_allowed());
CREATE POLICY "Restrict personal progress access" ON public.watch_progress AS RESTRICTIVE FOR ALL TO authenticated USING(public.account_access_allowed()) WITH CHECK(public.account_access_allowed());
CREATE POLICY "Restrict personal unlock access" ON public.series_unlocks AS RESTRICTIVE FOR ALL TO authenticated USING(public.account_access_allowed()) WITH CHECK(public.account_access_allowed());
CREATE POLICY "Restrict personal profile access" ON public.profiles AS RESTRICTIVE FOR ALL TO authenticated USING(public.account_access_allowed()) WITH CHECK(public.account_access_allowed());
CREATE POLICY "Restrict passkey access" ON public.passkey_credentials AS RESTRICTIVE FOR ALL TO authenticated USING(public.account_access_allowed()) WITH CHECK(public.account_access_allowed());
CREATE OR REPLACE FUNCTION public.record_viewer_presence(p_user uuid,p_session uuid,p_device text,p_name text,p_ip text,p_country text,p_city text,p_agent text,p_touch jsonb,p_state text,p_episode uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE previous public.viewer_sessions; elapsed numeric:=0; BEGIN
 IF p_state NOT IN ('active','idle','watching') THEN RAISE EXCEPTION 'Invalid presence'; END IF;
 INSERT INTO public.viewer_sessions(session_id,user_id,device_hash,device_name,ip,country,city,user_agent,first_touch,last_touch,state,current_episode_id) VALUES(p_session,p_user,p_device,p_name,p_ip,p_country,p_city,p_agent,p_touch,p_touch,p_state,p_episode) ON CONFLICT(session_id) DO NOTHING;
 SELECT * INTO previous FROM public.viewer_sessions WHERE session_id=p_session FOR UPDATE;
 IF previous.user_id<>p_user OR previous.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'Session unavailable'; END IF;
 IF previous.state='watching' AND previous.current_episode_id IS NOT NULL THEN elapsed:=greatest(0,least(30,extract(epoch FROM now()-previous.last_seen_at))); INSERT INTO public.viewer_watch_history(user_id,session_id,episode_id,watched_seconds) VALUES(p_user,p_session,previous.current_episode_id,elapsed) ON CONFLICT(session_id,episode_id) DO UPDATE SET watched_seconds=viewer_watch_history.watched_seconds+elapsed,last_watched_at=now(); END IF;
 UPDATE public.viewer_sessions SET device_hash=p_device,device_name=p_name,ip=p_ip,country=p_country,city=p_city,user_agent=p_agent,last_touch=p_touch,state=p_state,current_episode_id=p_episode,watched_seconds=watched_seconds+elapsed,last_seen_at=now() WHERE session_id=p_session;
 END; $$;
REVOKE ALL ON FUNCTION public.record_viewer_presence(uuid,uuid,text,text,text,text,text,text,jsonb,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.record_viewer_presence(uuid,uuid,text,text,text,text,text,text,jsonb,text,uuid) TO service_role;